<h1><?= $user?'Edit User':'Add User' ?></h1><form class='form-card' method='POST' action='<?= $action ?>'><?= csrf_field() ?><label>Name</label><input name='full_name' value='<?= e($user['full_name']??'') ?>' required><label>Email</label><input type='email' name='email' value='<?= e($user['email']??'') ?>' required><?php if(!$user): ?><label>Password</label><input type='password' name='password' required><?php endif; ?><label>Phone</label><input name='phone' value='<?= e($user['phone']??'') ?>'><label>Role</label><select name='role'><?php foreach(['Customer','Host','Staff','Admin'] as $r): ?><option value='<?= $r ?>' <?= ($user['role']??'')===$r?'selected':'' ?>><?= $r ?></option><?php endforeach; ?></select><label><input type='checkbox' name='is_active' <?= ($user['is_active']??1)?'checked':'' ?>> Active</label><button class='btn'>Save</button></form>
